 "content": "def transform(grid):
    """Extend numbered markers along their associated fixed paths; mark crossings."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    segments = []

    # (dr, dc, length, shape): copy endpoint offset from each source marker.
    rules = {
        1: (-1, 2, 2, "elbow"),
        2: (0, -4, 4, "line"),
        3: (3, 0, 3, "line"),
        6: (-6, 0, 6, "line"),
    }
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in rules:
                continue
            dr, dc, length, shape = rules[color]
            er, ec = r + dr, c + dc
            if not (0 <= er < h and 0 <= ec < w):
                continue
            if shape == "elbow":
                points = [(r, c + j) for j in range(1, dc + 1)]
                points += [(r - 1, ec)]
            elif dr == 0:
                step = 1 if dc > 0 else -1
                points = [(r, c + step * j) for j in range(1, length)]
            else:
                step = 1 if dr > 0 else -1
                points = [(r + step * j, c) for j in range(1, length)]
            for pr, pc in points:
                if 0 <= pr < h and 0 <= pc < w and out[pr][pc] == 0:
                    out[pr][pc] = 5
            # Preserve original marker; place the translated copy.
            out[er][ec] = color
            if shape == "line":
                segments.append(((r, c), (er, ec)))

    # A horizontal and vertical numbered path crossing creates a 4-ray.
    for (a, b) in segments:
        ar, ac = a
        br, bc = b
        for (d, e) in segments:
            dr, dc = d
            er, ec = e
            if ac == bc and dr == er and min(ar, br) <= dr <= max(ar, br) and min(dc, ec) <= ac <= max(dc, ec):
                ir, ic = dr, ac
            elif ar == br and dc == ec and min(ac, bc) <= dc <= max(ac, bc) and min(dr, er) <= ar <= max(dr, er):
                ir, ic = ar, dc
            else:
                continue
            # Ignore a degenerate same-orientation pair.
            if not ((ac == bc and dr == er) or (ar == br and dc == ec)):
                continue
            out[ir][ic] = 4
            rr, cc = ir + 1, ic - 1
            while 0 <= rr < h and 0 <= cc < w:
                # The diagonal ray is the crossing mark and its continuation.
                out[rr][cc] = 4
                rr += 1
                cc -= 1
    return out


